// Prayer times - Aladhan API, method 5 (Egyptian General Authority). English output.
const TZ = 'Africa/Cairo';
const LAT = 30.584138;
const LON = 31.495866;
const METHOD = 5;
const PLACE = 'Zagazig, Egypt';
const PRAYERS = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];

const input = $input.first().json || {};
const now = new Date();
const cairoToday = new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit',
}).format(now);
const nowHM = new Intl.DateTimeFormat('en-GB', {
  timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).format(now);
const toMin = (hm) => {
  const parts = String(hm).split(':');
  return Number(parts[0]) * 60 + Number(parts[1] || 0);
};
const nowM = toMin(nowHM);
const fmt12 = (hm) => {
  const parts = String(hm).split(':');
  const hour = Number(parts[0]);
  const minute = Number(parts[1] || 0);
  const suffix = hour < 12 ? 'AM' : 'PM';
  const display = ((hour + 11) % 12) + 1;
  return display + ':' + String(minute).padStart(2, '0') + ' ' + suffix;
};
const addDays = (iso, amount) => {
  const date = new Date(iso + 'T12:00:00Z');
  date.setUTCDate(date.getUTCDate() + amount);
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(date);
};

let base = String(input.date || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(base)) base = cairoToday;
let days = Number(input.days);
if (!Number.isFinite(days)) days = 1;
days = Math.max(1, Math.min(7, Math.round(days)));

const dates = [];
for (let index = 0; index < days; index += 1) dates.push(addDays(base, index));

const httpRequest = this.helpers.httpRequest.bind(this.helpers);
const monthCache = {};
const clean = (value) => String(value || '').trim().split(' ')[0];

async function monthTimings(yearMonth) {
  if (monthCache[yearMonth]) return monthCache[yearMonth];
  const [year, month] = yearMonth.split('-');
  const response = await httpRequest({
    method: 'GET',
    url: 'https://api.aladhan.com/v1/calendar?latitude=' + LAT + '&longitude=' + LON
      + '&method=' + METHOD + '&month=' + Number(month) + '&year=' + Number(year),
    json: true,
    timeout: 20000,
  });
  const rows = (response && response.data) || [];
  const map = {};
  for (const row of rows) {
    const gregorian = row && row.date && row.date.gregorian ? row.date.gregorian.date : null;
    if (!gregorian) continue;
    const iso = gregorian.split('-').reverse().join('-');
    const timings = row.timings || {};
    const times = {};
    for (const prayer of PRAYERS) times[prayer] = clean(timings[prayer]);
    const rawHijri = row.date && row.date.hijri;
    const hijri = rawHijri ? {
      day: rawHijri.day,
      month: rawHijri.month && rawHijri.month.en,
      year: rawHijri.year,
      designation: rawHijri.designation && rawHijri.designation.abbreviated,
    } : null;
    map[iso] = { times: times, hijri: hijri };
  }
  monthCache[yearMonth] = map;
  return map;
}

try {
  const items = [];
  for (const iso of dates) {
    const map = await monthTimings(iso.slice(0, 7));
    const entry = map[iso];
    if (!entry || !entry.times || !entry.times.Fajr) {
      return [{ json: { ok: false, error: 'Could not fetch prayer times for ' + iso + ' from Aladhan.' } }];
    }
    const times12 = {};
    for (const prayer of PRAYERS) times12[prayer] = fmt12(entry.times[prayer]);
    const item = {
      date: iso,
      location: PLACE,
      method: 'Egyptian General Authority (5)',
      hijri: entry.hijri,
      times: entry.times,
      times_12h: times12,
    };
    if (iso === cairoToday) {
      let next = null;
      for (const prayer of PRAYERS) {
        const prayerMinute = toMin(entry.times[prayer]);
        if (prayerMinute > nowM) {
          next = {
            name: prayer,
            at: entry.times[prayer],
            at_12h: fmt12(entry.times[prayer]),
            in_minutes: prayerMinute - nowM,
          };
          break;
        }
      }
      if (!next) {
        const tomorrow = addDays(cairoToday, 1);
        const tomorrowMap = await monthTimings(tomorrow.slice(0, 7));
        const tomorrowEntry = tomorrowMap[tomorrow];
        if (tomorrowEntry && tomorrowEntry.times && tomorrowEntry.times.Fajr) {
          next = {
            name: 'Fajr',
            day: 'tomorrow',
            at: tomorrowEntry.times.Fajr,
            at_12h: fmt12(tomorrowEntry.times.Fajr),
            in_minutes: (24 * 60 - nowM) + toMin(tomorrowEntry.times.Fajr),
          };
        }
      }
      item.is_today = true;
      item.now_cairo = nowHM;
      item.next_prayer = next || { name: null, note: 'The next prayer is Fajr tomorrow.' };
    }
    items.push({ json: { ok: true, ...item } });
  }
  return items;
} catch (error) {
  return [{ json: { ok: false, error: 'Could not reach Aladhan: ' + (error && error.message ? error.message : String(error)) } }];
}
